INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9069e1e8-a472-5f4e-9db4-ac8d1c8d6e3b', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', $$An IS-IS Level 1 router needs to reach a prefix in another area. The nearest L1/L2 router has the attached bit set. What is the expected result?$$::text, $$[{"id": "A", "text": "LOCAL_PREF is evaluated before AS_PATH; the higher LOCAL_PREF route wins.", "is_correct": false}, {"id": "B", "text": "The DR builds the shared tree toward the RP using (*,239.1.1.1).", "is_correct": false}, {"id": "C", "text": "The L1 router installs a default route toward the L1/L2 router.", "is_correct": true}, {"id": "D", "text": "BGP advertises the new site ID and pseudowire labels to other PEs.", "is_correct": false}]$$::jsonb, $$Given An IS-IS Level 1 router needs to reach a prefix in another area. and The nearest L1/L2 router has the attached bit set., the result is: The L1 router installs a default route toward the L1/L2 router.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$2.0 IS-IS$$::text, 15.0, 'e33cd3cbf7f3f77c', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00d1fc45-ffcf-5412-972d-606a48e62426', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', $$An MPLS LSP uses RSVP with fast reroute enabled. A protected link fails. What is the expected result?$$::text, $$[{"id": "A", "text": "BGP advertises the new site ID and pseudowire labels to other PEs.", "is_correct": false}, {"id": "B", "text": "Other VRFs importing 65000:1 receive the default route.", "is_correct": false}, {"id": "C", "text": "Traffic is rerouted along the bypass LSP within tens of milliseconds.", "is_correct": true}, {"id": "D", "text": "The DR builds the shared tree toward the RP using (*,239.1.1.1).", "is_correct": false}]$$::jsonb, $$Given An MPLS LSP uses RSVP with fast reroute enabled. and A protected link fails., the result is: Traffic is rerouted along the bypass LSP within tens of milliseconds.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$4.0 MPLS$$::text, 15.0, '898f0f741a3a284d', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65024bdf-93eb-5d71-a2ae-ac38fac63fbb', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', $$A BGP route has a shorter AS_PATH but lower LOCAL_PREF. All higher attributes are equal except LOCAL_PREF and AS_PATH. What is the expected result?$$::text, $$[{"id": "A", "text": "The DR builds the shared tree toward the RP using (*,239.1.1.1).", "is_correct": false}, {"id": "B", "text": "The L1 router installs a default route toward the L1/L2 router.", "is_correct": false}, {"id": "C", "text": "LOCAL_PREF is evaluated before AS_PATH; the higher LOCAL_PREF route wins.", "is_correct": true}, {"id": "D", "text": "BGP advertises the new site ID and pseudowire labels to other PEs.", "is_correct": false}]$$::jsonb, $$Given A BGP route has a shorter AS_PATH but lower LOCAL_PREF. and All higher attributes are equal except LOCAL_PREF and AS_PATH., the result is: LOCAL_PREF is evaluated before AS_PATH; the higher LOCAL_PREF route wins.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$3.0 BGP$$::text, 15.0, '5e779cee99b4975e', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d709a93f-d77f-57ca-adef-6a38af28a153', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', $$An L3VPN CE advertises a default route to the PE. The PE exports the default route with route target 65000:1. What is the expected result?$$::text, $$[{"id": "A", "text": "BGP advertises the new site ID and pseudowire labels to other PEs.", "is_correct": false}, {"id": "B", "text": "Other VRFs importing 65000:1 receive the default route.", "is_correct": true}, {"id": "C", "text": "The L1 router installs a default route toward the L1/L2 router.", "is_correct": false}, {"id": "D", "text": "Traffic is rerouted along the bypass LSP within tens of milliseconds.", "is_correct": false}]$$::jsonb, $$Given An L3VPN CE advertises a default route to the PE. and The PE exports the default route with route target 65000:1., the result is: Other VRFs importing 65000:1 receive the default route.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$5.0 L3VPN$$::text, 15.0, '732d7bdbc551a40f', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ce99d8d-a855-5b1a-b09a-b770dbdd7162', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', $$A VPLS site uses BGP signaling (Kompella). A new site is added. What is the expected result?$$::text, $$[{"id": "A", "text": "Other VRFs importing 65000:1 receive the default route.", "is_correct": false}, {"id": "B", "text": "BGP advertises the new site ID and pseudowire labels to other PEs.", "is_correct": true}, {"id": "C", "text": "Traffic is rerouted along the bypass LSP within tens of milliseconds.", "is_correct": false}, {"id": "D", "text": "The DR builds the shared tree toward the RP using (*,239.1.1.1).", "is_correct": false}]$$::jsonb, $$Given A VPLS site uses BGP signaling (Kompella). and A new site is added., the result is: BGP advertises the new site ID and pseudowire labels to other PEs.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$6.0 L2VPN$$::text, 10.0, '7490646833db0260', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3cfb9998-9cb7-55de-a977-55fffc608ac9', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', $$PIM-SM is deployed without any source. A receiver sends an IGMP join for group 239.1.1.1. What is the expected result?$$::text, $$[{"id": "A", "text": "LOCAL_PREF is evaluated before AS_PATH; the higher LOCAL_PREF route wins.", "is_correct": false}, {"id": "B", "text": "The L1 router installs a default route toward the L1/L2 router.", "is_correct": false}, {"id": "C", "text": "BGP advertises the new site ID and pseudowire labels to other PEs.", "is_correct": false}, {"id": "D", "text": "The DR builds the shared tree toward the RP using (*,239.1.1.1).", "is_correct": true}]$$::jsonb, $$Given PIM-SM is deployed without any source. and A receiver sends an IGMP join for group 239.1.1.1., the result is: The DR builds the shared tree toward the RP using (*,239.1.1.1).$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$7.0 Multicast$$::text, 10.0, '341191aef986ae8a', true) ON CONFLICT (id) DO NOTHING;
