INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ad9cf63-4cef-556e-83f4-c3fba6d76179', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'simlet', 4, 'analyze', $$How many LDP neighbors are established?

user@PE> show ldp neighbor
Address            Interface          Peer-id             Holdtime
10.1.1.2           ge-0/0/0.0         2.2.2.2:0           12
10.1.1.3           ge-0/0/0.0         3.3.3.3:0           11$$::text, $$[{"id": "A", "text": "1", "is_correct": false}, {"id": "B", "text": "2", "is_correct": true}, {"id": "C", "text": "3", "is_correct": false}, {"id": "D", "text": "0", "is_correct": false}]$$::jsonb, $$The output lists two LDP neighbors.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$4.0 MPLS$$::text, 15.0, '2d674277d3b8f904', true) ON CONFLICT (id) DO NOTHING;
