INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eaa03a3f-125c-524b-a67c-ad9f69227e58', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'simlet', 4, 'analyze', $$What is the state of the LSP to 10.0.0.6?

user@P> show mpls lsp
Ingress LSP: 1 sessions
To              From            State Rt P     ActivePath       LSPname
10.0.0.6        10.0.0.1        Up    0 *     primary          to-PE2$$::text, $$[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Up", "is_correct": true}, {"id": "C", "text": "Active", "is_correct": false}, {"id": "D", "text": "Bypass", "is_correct": false}]$$::jsonb, $$The State column shows Up.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$4.0 MPLS$$::text, 15.0, '1e369cdc908e88aa', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b830251-769e-5999-8920-58139b41d388', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'simlet', 4, 'analyze', $$How is traffic to 192.168.1.0/24 forwarded?

user@PE> show route table vpn-a.inet.0 192.168.1.0/24

vpn-a.inet.0: 1 destinations, 1 routes (1 active, 0 holddown, 0 hidden)
+ = Active Route, - = Last Active, * = Both

192.168.1.0/24   *[BGP/170] 00:10:22, localpref 100, from 10.0.0.5
                      AS path: I, validation-state: unverified
                    > to 10.0.0.5 via ge-0/0/2.0, label-switched-path to-PE2$$::text, $$[{"id": "A", "text": "Via IP next-hop only", "is_correct": false}, {"id": "B", "text": "Via LSP to-PE2", "is_correct": true}, {"id": "C", "text": "Via default route", "is_correct": false}, {"id": "D", "text": "It is dropped", "is_correct": false}]$$::jsonb, $$The route resolves to label-switched-path to-PE2.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$5.0 L3VPN$$::text, 15.0, 'f3922f5714fbda21', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a4bb8cc-c70d-57cd-82a2-d9229e65ea2d', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'multiple-choice', 4, 'analyze', $$Which protocols can signal MPLS labels? (Choose two.)$$::text, $$[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "PIM", "is_correct": false}, {"id": "D", "text": "OSPF", "is_correct": false}, {"id": "E", "text": "RSVP", "is_correct": true}, {"id": "F", "text": "LDP", "is_correct": true}]$$::jsonb, $$LDP and RSVP are MPLS label signaling protocols. BGP can signal VPN labels, but not transport labels by default.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$4.0 MPLS$$::text, 15.0, 'ec2db97059ba7ddb', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3eb9e7b-e26c-5b3c-bda8-c91738a8a4e3', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'multiple-choice', 4, 'analyze', $$Which statements differentiate VPLS and VPWS? (Choose two.)$$::text, $$[{"id": "A", "text": "VPLS is point-to-point", "is_correct": false}, {"id": "B", "text": "VPWS is point-to-point", "is_correct": true}, {"id": "C", "text": "VPLS uses pseudowires only", "is_correct": false}, {"id": "D", "text": "VPWS supports MAC learning", "is_correct": false}, {"id": "E", "text": "VPWS requires BGP signaling", "is_correct": false}, {"id": "F", "text": "VPLS is multipoint", "is_correct": true}]$$::jsonb, $$VPLS provides multipoint Layer 2 LAN; VPWS provides point-to-point Layer 2 circuit.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$6.0 L2VPN$$::text, 10.0, 'c70045cbf88b1e90', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7ce2200-a8b5-521a-ad85-c0b1b1d9d504', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'multiple-choice', 4, 'analyze', $$Which statements about PIM sparse mode are true? (Choose two.)$$::text, $$[{"id": "A", "text": "Source registers directly with receivers", "is_correct": false}, {"id": "B", "text": "Receivers join (*,G) toward the RP", "is_correct": true}, {"id": "C", "text": "Floods traffic by default", "is_correct": false}, {"id": "D", "text": "Does not use RP", "is_correct": false}, {"id": "E", "text": "Uses a rendezvous point", "is_correct": true}]$$::jsonb, $$PIM-SM uses an RP; receivers join shared tree (*,G). SSM uses (S,G) without RP.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$7.0 Multicast$$::text, 10.0, '752aedf9237443ea', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c11a509-69ec-5e6e-81c8-997c0f390ddc', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'multiple-choice', 4, 'analyze', $$Which components are required for a Layer 3 VPN? (Choose two.)$$::text, $$[{"id": "A", "text": "Route distinguisher", "is_correct": true}, {"id": "B", "text": "IS-IS NET", "is_correct": false}, {"id": "C", "text": "OSPF area ID", "is_correct": false}, {"id": "D", "text": "PIM RP", "is_correct": false}, {"id": "E", "text": "Route target", "is_correct": true}]$$::jsonb, $$RD makes prefixes unique; RT controls import/export. IS-IS NET, OSPF area, PIM RP, BFD are not required for L3VPN itself.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$5.0 L3VPN$$::text, 15.0, '4b5e22bc440788e1', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3211e25-e1aa-553e-88fe-a435802c0e6e', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'multiple-choice', 4, 'analyze', $$Which actions influence inbound traffic with BGP? (Choose two.)$$::text, $$[{"id": "A", "text": "Next-hop self", "is_correct": false}, {"id": "B", "text": "Weight", "is_correct": false}, {"id": "C", "text": "LOCAL_PREF", "is_correct": false}, {"id": "D", "text": "MED", "is_correct": true}, {"id": "E", "text": "Communities for outbound only", "is_correct": false}, {"id": "F", "text": "AS_PATH prepending", "is_correct": true}]$$::jsonb, $$AS_PATH prepending and MED influence how external ASes send traffic inbound. LOCAL_PREF and Weight influence outbound.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$3.0 BGP$$::text, 15.0, 'c47512e4f02e363c', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
