INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e830fa1-8dd4-5c5d-a3c7-bdd260100473', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'multiple-choice', 4, 'analyze', $$Which statements about RSVP-TE are true? (Choose two.)$$::text, $$[{"id": "A", "text": "RSVP-TE can reserve bandwidth", "is_correct": true}, {"id": "B", "text": "RSVP-TE supports explicit paths", "is_correct": true}, {"id": "C", "text": "RSVP-TE is only for L2VPN", "is_correct": false}, {"id": "D", "text": "RSVP-TE does not support traffic engineering", "is_correct": false}, {"id": "E", "text": "RSVP-TE uses LDP for label distribution", "is_correct": false}, {"id": "F", "text": "RSVP-TE cannot use Fast Reroute", "is_correct": false}]$$::jsonb, $$RSVP-TE supports bandwidth reservation, explicit paths, and fast reroute. It does not use LDP.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$4.0 MPLS$$::text, 15.0, 'bbc122d36b2a5dec', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dfb07c98-ab8c-5b88-8ac5-9ee0f7577842', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'multiple-choice', 4, 'analyze', $$Which statements describe hub-and-spoke VPNs? (Choose two.)$$::text, $$[{"id": "A", "text": "Each spoke imports all RTs", "is_correct": false}, {"id": "B", "text": "Full mesh of BGP sessions is required", "is_correct": false}, {"id": "C", "text": "Hub-and-spoke requires VPLS", "is_correct": false}, {"id": "D", "text": "The hub can apply policy to inter-spoke traffic", "is_correct": true}, {"id": "E", "text": "Spokes communicate directly", "is_correct": false}, {"id": "F", "text": "Spokes exchange traffic through the hub", "is_correct": true}]$$::jsonb, $$In hub-and-spoke, all traffic passes through the hub, allowing policy enforcement. Spokes do not communicate directly.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$5.0 L3VPN$$::text, 15.0, '6ef098c725ac1ed6', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
